To implement the feature request, we'll add `from_arrow` methods to `GeoDataFrame` and `GeoSeries` to support importing data from Arrow tables into GeoPandas objects. Here's the implementation plan:

### 1. Add `from_arrow` to `GeoSeries`
```python
def from_arrow(cls, data, index=None, **kwargs):
    """Alternate constructor to create a GeoSeries from an Arrow array with GeoArrow extension type."""
    if isinstance(data, (pa.Array, pa.ChunkedArray)):
        data = data.combine_chunks()
    elif hasattr(data, "__arrow_c_array__"):
        schema_capsule, array_capsule = data.__arrow_c_array__()
        field = pa.Field._import_from_c_capsule(schema_capsule)
        data = pa.Array._import_from_c_capsule(field, array_capsule)

    geom_array = _arrow_array_to_geometry_array(data)
    return cls(geom_array, index=index, **kwargs)
```

### 2. Add `from_arrow` to `GeoDataFrame`
```python
def from_arrow(cls, data, geometry=None, **kwargs):
    """Alternate constructor to create a GeoDataFrame from an Arrow table with GeoArrow extension type."""
    geometry_columns = _get_geometry_columns_from_table(data)
    if not geometry_columns:
        raise ValueError("No geometry columns found in the Arrow table.")

    df = data.to_pandas()
    for col_name, field, ext_name in geometry_columns:
        arr = data.column(col_name).combine_chunks()
        crs = None
        if field.metadata:
            ext_metadata = field.metadata.get(b"ARROW:extension:metadata", b"{}")
            try:
                metadata = json.loads(ext_metadata.decode())
                if "crs" in metadata:
                    crs = metadata["crs"]
            except (json.JSONDecodeError, TypeError):
                pass
        geom_array = _arrow_array_to_geometry_array(arr, ext_name, crs=crs)
        df[col_name] = geom_array

    if geometry is None:
        geometry = geometry_columns[0][0]
    elif geometry not in dict(geometry_columns):
        raise ValueError(f"Specified geometry column '{geometry}' not found in geometry columns: {list(dict(geometry_columns).keys())}")

    return cls(df, geometry=geometry, **kwargs)
```

